.product-demand{margin-left:12px;color:#718395}.product-quote-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 14px}.product-payment{grid-column:1/-1}.product-payment :deep(.el-select),.product-quote-grid :deep(.el-date-editor),.product-quote-grid :deep(.el-select){width:100%}.quote-fixed-target strong,.quote-fixed-target small{display:block}.quote-fixed-target small{margin-top:4px;color:#718395}@media(max-width:760px){.product-quote-grid{grid-template-columns:1fr}.product-payment{grid-column:auto}}
