.participant-card{box-sizing:border-box;max-width:1600px;margin:0 auto 14px;padding:18px 20px;border:1px solid #dfe8e6;border-radius:10px;background:#fff}.participant-head{display:flex;justify-content:space-between;align-items:center}.participant-head small,.participant-head strong,.participant-head p{display:block}.participant-head small{color:#718395}.participant-head strong{margin-top:4px;color:#17324d}.participant-head p{margin:5px 0 0;color:#718395;font-size:13px}.participant-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:9px;margin-top:14px}.participant-item{display:flex;justify-content:space-between;align-items:center;padding:11px 12px;border:1px solid #e2ebe8;border-radius:8px;background:#f8fbfa}.participant-item span,.participant-item small{display:block}.participant-item small{margin-top:3px;color:#8493a1;font-size:11px}.participant-item>div{display:flex;align-items:center;gap:5px}@media(max-width:850px){.participant-head{align-items:flex-start;gap:12px;flex-direction:column}.participant-list{grid-template-columns:1fr}}
